class Solution:
    def unpack(self, bundle: str) -> List[str]:
        out, i, n = [], 0, len(bundle)
        while i < n:
            j, size = i, 0
            while bundle[j] != "#":
                size = size * 10 + int(bundle[j])
                j += 1
            out.append(bundle[j + 1:j + 1 + size])
            i = j + 1 + size
        return out

