class Solution {
    public List<String> unpack(String bundle) {
        List<String> out = new ArrayList<>();
        int i = 0, n = bundle.length();
        while (i < n) {
            int j = i, size = 0;
            while (bundle.charAt(j) != '#') size = size * 10 + (bundle.charAt(j++) - '0');
            out.add(bundle.substring(j + 1, j + 1 + size));
            i = j + 1 + size;
        }
        return out;
    }
}

