class Solution {
public:
    vector<string> unpack(string& bundle) {
        vector<string> out;
        int i = 0, n = bundle.size();
        while (i < n) {
            int j = i, size = 0;
            while (bundle[j] != '#') size = size * 10 + (bundle[j++] - '0');
            out.push_back(bundle.substr(j + 1, size));
            i = j + 1 + size;
        }
        return out;
    }
};

