char** unpack(char* bundle, int* returnSize) {
    int n = strlen(bundle), i = 0, count = 0;
    char** out = malloc((n / 2 + 1) * sizeof(char*));
    while (i < n) {
        int j = i, size = 0;
        while (bundle[j] != '#') size = size * 10 + (bundle[j++] - '0');
        char* item = malloc(size + 1);
        memcpy(item, bundle + j + 1, size);
        item[size] = '\0';
        out[count++] = item;
        i = j + 1 + size;
    }
    *returnSize = count;
    return out;
}
